// -----------------------------------------------------------------------------
// unit_hype_column: the HYPE land column against HYPE itself.
//
// Usage: lsdtt-test-hype-column <oracle_dir>
//   oracle_dir = tests/expected/hype (committed; generated by
//   tests/scripts/generate_hype_oracle.py from HYPE 5.36.0).
//
// For every oracle case with per-class output, the set-up is loaded from
// <case>/lsdtt_input, every (sub-basin, class) unit is stepped through the
// committed forcing, and each per-class variable HYPE wrote is compared, every
// timestep, with the lsdtt3 value.
//
// TOLERANCE. HYPE runs in single precision and printed 9 significant
// figures; lsdtt3 runs in double. The oracle README records the precision
// floor: the largest single-vs-double difference over all cases is
// 1.08e-4 mm (relative 3.8e-6). A comparison passes when
//     |lsdtt - hype| <= k_abs_tol + k_rel_tol * |hype|
// with k_abs_tol and k_rel_tol a small factor above that floor. The largest
// differences actually seen are printed per variable so a tightening (or a
// drift) is visible in the log.
//
// It also checks, without the oracle: the water balance of every unit on every
// step, the rain/snow ramp at its three regimes, and that percolation never
// fills a receiving layer beyond its pore volume.
// -----------------------------------------------------------------------------

#include <algorithm>
#include <array>
#include <cmath>
#include <cstdio>
#include <functional>
#include <iostream>
#include <map>
#include <string>
#include <vector>

#include "../../src/core/lsdtt_csv_table.hpp"
#include "../../src/core/lsdtt_distributed_hydrology_forcing.hpp"
#include "../../src/cpu/lsdtt_hype_column_cpu.hpp"
#include "../../src/cpu/lsdtt_hype_parameters.hpp"

namespace
{

int g_checks = 0;
int g_fails  = 0;

void check(bool ok, const std::string& what)
{
    ++g_checks;
    if (!ok)
    {
        ++g_fails;
        std::cout << "  FAIL: " << what << "\n";
    }
}

// A small factor (about 5x) above the oracle's measured precision floor.
constexpr double k_abs_tol = 5.0e-4;   // mm (or deg C for ctmp)
constexpr double k_rel_tol = 2.0e-5;

// Day of year from an ISO date "YYYY-MM-DD".
int day_of_year(const std::string& iso)
{
    const int y = std::stoi(iso.substr(0, 4));
    const int m = std::stoi(iso.substr(5, 2));
    const int d = std::stoi(iso.substr(8, 2));
    static const int cum[12] = {0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334};
    const bool leap = (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    return cum[m - 1] + d + ((leap && m > 2) ? 1 : 0);
}

struct unit_ref
{
    int subid;
    int class_id;
    lsdtt::hype_unit_constants constants;
    lsdtt::hype_unit_state state;
};

// The lsdtt3 value for a HYPE class-output variable code.
using getter = std::function<double(const lsdtt::hype_unit_fluxes&, const lsdtt::hype_unit_state&)>;

const std::map<std::string, getter>& variable_map()
{
    static const std::map<std::string, getter> m = {
        {"ctmp", [](const auto& f, const auto&) { return f.class_temperature_c; }},
        {"cprc", [](const auto& f, const auto&) { return f.class_precipitation_mm; }},
        {"snow", [](const auto&, const auto& s) { return s.snow_mm; }},
        {"snwc", [](const auto& f, const auto&) { return f.out_snwc_mm; }},
        {"melt", [](const auto& f, const auto&) { return f.out_melt_mm; }},
        {"infi", [](const auto& f, const auto&) { return f.out_infi_mm; }},
        {"epot", [](const auto& f, const auto&) { return f.epot_mm; }},
        {"evap", [](const auto& f, const auto&) { return f.evap_mm; }},
        {"sml1", [](const auto& f, const auto&) { return f.out_sml_mm[0]; }},
        {"sml2", [](const auto& f, const auto&) { return f.out_sml_mm[1]; }},
        {"sml3", [](const auto& f, const auto&) { return f.out_sml_mm[2]; }},
        {"ros1", [](const auto& f, const auto&) { return f.saturation_excess_mm; }},
        {"ros2", [](const auto& f, const auto&) { return f.excess_infiltration_mm; }},
        {"cro1", [](const auto& f, const auto&) { return f.soil_runoff_mm[0]; }},
        {"cro2", [](const auto& f, const auto&) { return f.soil_runoff_mm[1]; }},
        {"cro3", [](const auto& f, const auto&) { return f.soil_runoff_mm[2]; }},
        {"crun", [](const auto& f, const auto&) { return f.runoff_mm; }},
    };
    return m;
}

void run_case(const std::string& oracle_dir, const std::string& name,
              const std::vector<std::string>& variables)
{
    std::cout << "\n--- case " << name << " ---\n";
    const std::string in = oracle_dir + "/" + name + "/lsdtt_input";
    const lsdtt::hype_setup setup = lsdtt::load_hype_setup_directory(in);

    // Forcing: precipitation in mm (via the depth loader, which returns
    // metres), temperature in deg C, day of year from the date column.
    const std::string fpath = in + "/forcing.csv";
    const std::vector<double> prec_m =
        lsdtt::load_distributed_hydrology_depth_series(fpath, "precipitation_metres", "precipitation_mm");
    const std::vector<double> temp_c =
        lsdtt::load_distributed_hydrology_temperature_series(fpath, "temperature_c");
    const lsdtt::lsdtt_csv_table ftab = lsdtt::load_csv_table(fpath);
    std::vector<int> doy;
    for (const auto& row : ftab.rows) doy.push_back(day_of_year(lsdtt::csv_row_string(row, "date")));
    const std::size_t n_steps = prec_m.size();
    check(temp_c.size() == n_steps && doy.size() == n_steps, name + ": forcing columns have equal length");

    // Units: every (sub-basin, class) pair with a non-zero fraction.
    auto find_landuse = [&](int code) { for (const auto& r : setup.landuse) if (r.code == code) return r; throw std::runtime_error("landuse"); };
    auto find_soil    = [&](int code) { for (const auto& r : setup.soils) if (r.code == code) return r; throw std::runtime_error("soil"); };
    auto find_class   = [&](int id)   { for (const auto& r : setup.classes) if (r.class_id == id) return r; throw std::runtime_error("class"); };
    auto find_sub     = [&](int id)   { for (const auto& r : setup.subbasins) if (r.subid == id) return r; throw std::runtime_error("subbasin"); };

    std::vector<unit_ref> units;
    for (const auto& sc : setup.subbasin_classes)
    {
        if (!(sc.fraction > 0.0)) continue;
        const auto cd = find_class(sc.class_id);
        unit_ref u{sc.subid, sc.class_id,
                   lsdtt::make_hype_unit_constants(setup.general, find_landuse(cd.landuse),
                                                   find_soil(cd.soil), cd,
                                                   find_sub(sc.subid).slope_mean_percent, sc.dh_m),
                   {}};
        u.state = lsdtt::initial_hype_unit_state(u.constants);
        units.push_back(u);
    }

    // Simulated series: [variable][unit][step]
    std::map<std::string, std::vector<std::vector<double>>> sim;
    for (const auto& v : variables) sim[v].assign(units.size(), std::vector<double>(n_steps, 0.0));

    double worst_balance = 0.0;
    for (std::size_t t = 0; t < n_steps; ++t)
    {
        const lsdtt::hype_unit_forcing forcing{prec_m[t] * 1000.0, temp_c[t], doy[t]};
        for (std::size_t u = 0; u < units.size(); ++u)
        {
            const double before = lsdtt::hype_unit_storage_mm(units[u].state);
            lsdtt::hype_unit_fluxes f;
            lsdtt::hype_unit_step(setup.general, units[u].constants, forcing, units[u].state, f);
            const double after = lsdtt::hype_unit_storage_mm(units[u].state);
            const double residual = (after - before) - (f.class_precipitation_mm - f.evap_mm - f.runoff_mm);
            worst_balance = std::max(worst_balance, std::fabs(residual));
            for (const auto& v : variables) sim[v][u][t] = variable_map().at(v)(f, units[u].state);
        }
    }
    std::printf("  water balance: largest |residual| over all units and steps = %.3e mm\n", worst_balance);
    check(worst_balance < 1.0e-9, name + ": every unit closes its water balance to 1e-9 mm");

    // Compare with HYPE.
    for (const auto& v : variables)
    {
        const std::string path = oracle_dir + "/" + name + "/expected/class_" + v + ".csv";
        const lsdtt::lsdtt_csv_table ref = lsdtt::load_csv_table(path);
        check(ref.rows.size() == n_steps, name + "/" + v + ": oracle has one row per step");
        double max_abs = 0.0, max_rel = 0.0;
        int n_out = 0;
        std::string first_bad;
        for (std::size_t u = 0; u < units.size(); ++u)
        {
            const std::string col = std::to_string(units[u].subid) + "_" + std::to_string(units[u].class_id);
            if (!lsdtt::csv_has_column(ref, col))
            {
                check(false, name + "/" + v + ": oracle column " + col + " missing");
                continue;
            }
            for (std::size_t t = 0; t < n_steps && t < ref.rows.size(); ++t)
            {
                const double h = lsdtt::csv_row_double_required(ref.rows[t], col, path, static_cast<int>(t) + 1);
                const double l = sim[v][u][t];
                const double d = std::fabs(l - h);
                max_abs = std::max(max_abs, d);
                if (std::fabs(h) > 1.0e-3) max_rel = std::max(max_rel, d / std::fabs(h));
                if (d > k_abs_tol + k_rel_tol * std::fabs(h))
                {
                    if (n_out == 0)
                    {
                        char buf[200];
                        std::snprintf(buf, sizeof(buf), "%s step %zu: lsdtt %.9g vs HYPE %.9g",
                                      col.c_str(), t + 1, l, h);
                        first_bad = buf;
                    }
                    ++n_out;
                }
            }
        }
        std::printf("  %-5s max |diff| %.3e  max rel %.3e  out of tolerance %d\n",
                    v.c_str(), max_abs, max_rel, n_out);
        check(n_out == 0, name + "/" + v + ": matches HYPE within tolerance" +
                          (first_bad.empty() ? "" : " (first: " + first_bad + ")"));
    }
}

void analytic_checks()
{
    std::cout << "\n--- analytic checks ---\n";
    // Rain/snow ramp (atm_proc.f90:476): tt = ttmp + ttpd = 1, half-width 2.
    check(lsdtt::hype_rain_fraction(5.0, -5.0, 0.5, 0.5, 2.0) == 0.0, "ramp: all snow below tt - ttpi");
    check(lsdtt::hype_rain_fraction(5.0, 3.0, 0.5, 0.5, 2.0) == 1.0, "ramp: all rain at tt + ttpi");
    check(std::fabs(lsdtt::hype_rain_fraction(5.0, 1.0, 0.5, 0.5, 2.0) - 0.5) < 1e-15, "ramp: half at tt");
    check(std::fabs(lsdtt::hype_rain_fraction(5.0, 0.0, 0.5, 0.5, 2.0) - 0.25) < 1e-15, "ramp: linear inside");
    check(lsdtt::hype_rain_fraction(0.0, 10.0, 0.5, 0.5, 2.0) == 0.0, "ramp: no precipitation gives fraction 0");

    // Percolation never fills a receiving layer beyond its pore volume, and
    // conserves water. Sweep a range of states.
    lsdtt::hype_general_parameters g;
    lsdtt::hype_landuse_parameters lu;
    lsdtt::hype_soil_parameters so;
    so.wcwp = 0.1; so.wcfc = 0.2; so.wcep = 0.15; so.mperc1 = 25.0; so.mperc2 = 18.0;
    lsdtt::hype_class_definition cd;
    cd.class_id = 1; cd.landuse = 1; cd.soil = 1; cd.n_layers = 3;
    cd.layer_bottom_m = {0.1, 0.4, 1.0};
    const auto c = lsdtt::make_hype_unit_constants(g, lu, so, cd, 5.0, 0.0);
    bool overfill = false, leaked = false, overcap = false;
    for (double w1 = 20.0; w1 <= 60.0; w1 += 7.0)
        for (double w2 = 80.0; w2 <= 135.0; w2 += 9.0)
            for (double w3 = 170.0; w3 <= 270.0; w3 += 13.0)
            {
                std::array<double, 3> w = {w1, w2, w3};
                const double before = w[0] + w[1] + w[2];
                std::array<double, 2> perc{0.0, 0.0};
                const std::array<double, 3> w2_before = w;
                lsdtt::hype_percolation(c, w, perc);
                if (w[1] > std::max(c.pw_mm[1], w2_before[1]) + 1e-12) overfill = true;
                if (w[2] > std::max(c.pw_mm[2], w2_before[2]) + 1e-12) overfill = true;
                if (std::fabs(w[0] + w[1] + w[2] - before) > 1e-12) leaked = true;
                if (perc[0] > so.mperc1 + 1e-12 || perc[1] > so.mperc2 + 1e-12) overcap = true;
            }
    check(!overfill, "percolation never fills a receiving layer beyond its pore volume");
    check(!leaked, "percolation conserves water");
    check(!overcap, "percolation never exceeds mperc1/mperc2");
}

} // namespace

int main(int argc, char* argv[])
{
    if (argc < 2)
    {
        std::cerr << "usage: lsdtt-test-hype-column <oracle_dir>\n";
        return 2;
    }
    const std::string oracle = argv[1];
    try
    {
        analytic_checks();
        run_case(oracle, "snow", {"ctmp", "cprc", "snow", "snwc", "melt", "infi"});
        run_case(oracle, "et", {"epot", "evap", "sml1", "sml2", "sml3"});
        run_case(oracle, "diversion", {"infi", "ros2", "sml1", "sml2", "sml3", "evap"});
        run_case(oracle, "percolation", {"infi", "sml1", "sml2", "sml3", "evap"});
        run_case(oracle, "soil_runoff", {"crun", "cro1", "cro2", "cro3", "ros1", "ros2", "sml1", "sml2", "sml3"});
        run_case(oracle, "default_all", {"snow", "melt", "evap", "infi", "ros1", "ros2", "crun", "sml1", "sml2", "sml3"});
    }
    catch (const std::exception& e)
    {
        std::cout << "  FAIL: exception: " << e.what() << "\n";
        ++g_fails;
    }
    std::cout << "\n" << (g_checks - g_fails) << " / " << g_checks << " checks passed\n";
    std::cout << (g_fails == 0 ? "RESULT: PASS" : "RESULT: FAIL") << "\n";
    return g_fails == 0 ? 0 : 1;
}
